const state={session:null,tenants:[],workspacePage:1,releaseCatalogPage:1,activeReviewRun:null,activeWikiCandidate:null,activeWorkspaceRun:null,sessionRedirecting:false,headers:localSignedOut?localHeaders("business","",""):localHeaders()};
