function headers(){return state.session?.authentication==="local-development"?state.headers:{}}
// 认证过期只触发一次页面级跳转。调用方可识别该错误并避免将短暂的重登过程渲染成“工作区初始化失败”。
function sessionRedirectError(){const error=new Error("登录会话已失效，正在跳转重新登录");error.name="SessionRedirectError";return error}
async function api(path,options={}){const response=await fetch(path,{...options,headers:{"Content-Type":"application/json",...headers(),...(options.headers||{})}});if(!response.ok){let body={};try{body=await response.json()}catch{}if(response.status===401){if(!state.sessionRedirecting){state.sessionRedirecting=true;window.location.replace("/auth/relogin")}throw sessionRedirectError()};throw new Error(body.detail||`请求失败（${response.status}）`)}if(response.status===204)return null;return response.json()}
function statusClass(status){return `status ${status||"QUEUED"}`}
async function startWorkspaceEvents(runId){workspaceEventAbort?.abort();workspaceEventAbort=new AbortController();try{const response=await fetch(`/api/workspace/runs/${encodeURIComponent(runId)}/events?after_sequence=${workspaceEventCursor}`,{headers:headers(),signal:workspaceEventAbort.signal});if(!response.ok||!response.body)throw new Error("实时事件连接失败");const reader=response.body.getReader(),decoder=new TextDecoder();let buffer="";while(true){const next=await reader.read();if(next.done)break;buffer+=decoder.decode(next.value,{stream:true});const frames=buffer.split("\n\n");buffer=frames.pop()||"";let refresh=false;for(const frame of frames){const id=frame.match(/^id:\s*(\d+)/m);if(id)workspaceEventCursor=Number(id[1]);if(frame.includes("data:"))refresh=true}if(refresh){loadTasks();if(state.activeWorkspaceRun===runId&&$("#task-detail-dialog").open)await openTask(runId)}}}catch(error){if(error.name!=="AbortError")setTimeout(()=>{const detail=$("#task-detail");if(state.activeWorkspaceRun===runId&&$("#task-detail-dialog").open&&!terminal.has(detail.dataset.runStatus||""))startWorkspaceEvents(runId)},2000)}}
function showView(view){document.querySelectorAll(".view").forEach(node=>node.hidden=node.id!==`${view}-view`);document.querySelectorAll(".nav-item").forEach(node=>node.classList.toggle("active",node.dataset.view===view));$("#page-title").textContent={workspace:"我的任务",review:"审查中心",console:"平台控制台",identity:"租户与用户"}[view];$("#new-task-button").hidden=view!=="workspace";if(view==="review")loadReviewRuns();if(view==="identity"){if(hasPermission("tenant:read"))loadTenantCatalog();if(hasPermission("identity:users:read"))loadIdentityUsers()}if(view==="console"){loadConsoleServices();if(hasPermission("release:read"))loadReleaseCatalog();$("#release-operations-section").hidden=!(hasPermission("release:validate")||hasPermission("release:version:publish")||hasPermission("release:create")||hasPermission("release:promote")||hasPermission("release:pause")||hasPermission("release:rollback"));if(hasPermission("model:route:read"))loadModelRouteReleases();if(hasPermission("quota:read"))loadLlmQuotas();if(hasPermission("audit:export"))loadAuditExports();if(hasPermission("connector:artifact:dlq:read"))loadConnectorDlq();if(hasPermission("eval:golden:review"))loadGoldenCandidates()}}
function renderTasks(items){const root=$("#task-list");if(!items.length){root.innerHTML='<div class="empty-state">当前页没有任务记录。</div>';return}root.innerHTML="";items.forEach(item=>{const card=document.createElement("article");card.className="task-card";card.tabIndex=0;const text=item.summary?.answer||item.error_code||"任务正在等待下一步。";card.innerHTML=`<div><h3>${escapeHtml(item.agent_id||"Agent 任务")}</h3><p class="task-summary">${escapeHtml(text)}</p></div><div class="task-meta"><span class="${statusClass(item.status)}">${escapeHtml(item.status)}</span><time>${new Date(item.updated_at).toLocaleString()}</time></div>`;const open=()=>{state.activeWorkspaceRun=item.run_id;openTask(item.run_id)};card.addEventListener("click",open);card.addEventListener("keydown",event=>{if(event.key==="Enter")open()});root.append(card)})}
function paginationPages(current,total){if(total<=7)return Array.from({length:total},(_,index)=>index+1);const pages=new Set([1,2,total-1,total]);for(let page=current-1;page<=current+1;page++)if(page>0&&page<=total)pages.add(page);const sorted=[...pages].sort((left,right)=>left-right),items=[];for(const page of sorted){if(items.length&&page-items.at(-1)>1)items.push("…");items.push(page)}return items}
function renderTaskPagination(result){const root=$("#workspace-pagination"),totalItems=Number(result.total_items||0),pageSize=Number(result.limit||8),totalPages=Math.max(1,Math.ceil(totalItems/pageSize));state.workspacePage=Math.min(state.workspacePage,totalPages);root.hidden=totalItems<=pageSize;root.replaceChildren();if(root.hidden)return;const status=document.createElement("span");status.className="pagination-summary";status.textContent=`第 ${state.workspacePage} / ${totalPages} 页，共 ${totalItems} 条`;root.append(status);const addButton=(label,page,disabled=false)=>{const button=document.createElement("button");button.className="ghost pagination-button";button.type="button";button.textContent=label;button.disabled=disabled;button.addEventListener("click",()=>loadTasks(page));root.append(button)};addButton("上一页",state.workspacePage-1,state.workspacePage<=1);for(const item of paginationPages(state.workspacePage,totalPages)){if(item==="…"){const gap=document.createElement("span");gap.className="pagination-gap";gap.textContent=item;root.append(gap)}else{const button=document.createElement("button");button.className=`ghost pagination-button${item===state.workspacePage?" active":""}`;button.type="button";button.textContent=String(item);button.disabled=item===state.workspacePage;button.addEventListener("click",()=>loadTasks(item));root.append(button)}}addButton("下一页",state.workspacePage+1,state.workspacePage>=totalPages)}
async function loadTasks(page=state.workspacePage){state.workspacePage=Math.max(1,Number(page)||1);const root=$("#task-list");root.innerHTML='<div class="empty-state">正在加载任务…</div>';try{const result=await api(`/api/workspace/runs?limit=8&page=${state.workspacePage}`),totalPages=Math.max(1,Math.ceil(Number(result.total_items||0)/Number(result.limit||8)));if(state.workspacePage>totalPages){state.workspacePage=totalPages;return loadTasks(totalPages)}$("#workspace-scope").textContent=result.scope==="tenant-admin"?"每页显示 8 项租户任务摘要；可点击页码浏览历史与完整执行详情。":"每页显示 8 项本人或已共享任务；可点击页码浏览历史与完整执行详情。";renderTasks(result.items||[]);renderTaskPagination(result)}catch(error){root.innerHTML=`<div class="empty-state">${escapeHtml(error.message)}</div>`;$("#workspace-pagination").hidden=true}}
function renderReviewRuns(items){const root=$("#review-list");if(!items.length){root.innerHTML='<div class="empty-state">目前没有指派给你的审查任务。</div>';return}root.innerHTML="";items.forEach(item=>{const card=document.createElement("article");card.className="task-card review-card";card.tabIndex=0;const assignment=item.assignment||{};const text=item.summary?.answer||item.summary?.termination_reason||"该任务尚未生成最终结果。";card.innerHTML=`<div><p class="eyebrow">指派原因：${escapeHtml(assignment.reason||"未说明")}</p><h3>${escapeHtml(item.agent_id||"Agent 任务")}</h3><p>${escapeHtml(text)}</p><small>指派人：${escapeHtml(assignment.assigned_by||"系统")} · ${assignment.assigned_at?new Date(assignment.assigned_at).toLocaleString():""}</small></div><div class="task-meta"><span class="${statusClass(item.status)}">${escapeHtml(item.status)}</span><time>${new Date(item.updated_at).toLocaleString()}</time></div>`;const open=()=>{state.activeReviewRun=item.run_id;openReviewTask(item.run_id)};card.addEventListener("click",open);card.addEventListener("keydown",event=>{if(event.key==="Enter")open()});root.append(card)})}
async function loadReviewRuns(){const root=$("#review-list");if(!root)return;root.innerHTML='<div class="empty-state">正在加载审查队列…</div>';if(hasPermission("knowledge:review"))loadWikiCandidates();try{const result=await api("/api/review/runs?limit=30");renderReviewRuns(result.items||[])}catch(error){root.innerHTML=`<div class="empty-state">${escapeHtml(error.message)}</div>`}}
function renderWikiCandidates(items){const root=$("#wiki-candidate-list");if(!root)return;if(!items.length){root.innerHTML='<div class="empty-state">当前没有待审核的组织知识候选。</div>';return}root.replaceChildren();items.forEach(item=>{const draft=item.drafts?.[0]||{};const card=document.createElement("article");card.className="task-card review-card";card.innerHTML=`<div><p class="eyebrow">${escapeHtml(item.status||"pending_review")}</p><h3>${escapeHtml(draft.title||"未命名 Wiki 候选")}</h3><p>${escapeHtml(draft.summary||item.conclusion||"")}</p><small>Run：${escapeHtml(item.root_task_id||"-")} · 来源 ${item.sources?.length||0} 项</small></div><div class="task-meta"><button class="ghost">审核</button></div>`;card.querySelector("button").addEventListener("click",()=>{state.activeWikiCandidate=item;$("#wiki-review-title").textContent=`审核：${draft.title||item.candidate_id}`;$("#wiki-review-summary").textContent=`${draft.summary||item.conclusion||""}\n\n候选 ID：${item.candidate_id}`;$("#wiki-review-comment").value="";$("#wiki-review-dialog").showModal()});root.append(card)})}
async function loadWikiCandidates(){const section=$("#wiki-review-section"),root=$("#wiki-candidate-list");if(!section||!root||!hasPermission("knowledge:review"))return;section.hidden=false;root.innerHTML='<div class="empty-state">正在读取知识候选…</div>';try{renderWikiCandidates(await api("/api/review/wiki/candidates?status=pending_review&limit=50"))}catch(error){root.innerHTML=`<div class="empty-state">${escapeHtml(error.message)}</div>`}}
function openWikiCompiler(){const evidence=[...document.querySelectorAll("#task-detail .citation-list li strong")].map(node=>node.textContent.trim()).filter(Boolean),select=$("#wiki-evidence-select");select.replaceChildren();evidence.forEach(id=>{const option=document.createElement("option");option.value=id;option.textContent=id;option.selected=true;select.append(option)});if(!evidence.length){toast("此任务没有可授权的 Evidence，不能创建 Wiki 候选");return}const answer=$("#task-detail .answer")?.textContent?.trim()||"";$("#wiki-title-input").value="";$("#wiki-summary-input").value=answer.slice(0,1000);$("#wiki-body-input").value=answer;$("#wiki-tags-input").value="";$("#wiki-compile-dialog").showModal()}
async function openReviewTask(runId){try{const task=await api(`/api/review/runs/${encodeURIComponent(runId)}`);const evidence=(task.evidence||[]).map(item=>`<li><strong>${escapeHtml(item.evidence_id||"证据")}</strong> ${escapeHtml(item.source||"")}</li>`).join("")||"<li>没有可展示的证据标识。</li>";const graph=task.plan?.graph||{};const plan=task.plan?.status==="unavailable"?"此历史任务没有可用的已编译计划。":`执行器：${escapeHtml(task.plan?.executor_profile||"-")}<br>图：${escapeHtml(graph.graph_id||"-")}（${escapeHtml(graph.node_count||0)} 个节点）<br>能力：${escapeHtml((task.plan?.required_capabilities||[]).join("、")||"-")}<br>工具：${escapeHtml((task.plan?.tool_names||[]).join("、")||"-")}`;const approvalActions=task.approval?.required?'<button id="review-reject" class="ghost">拒绝</button><button id="review-approve" class="primary">批准</button>':'<button class="primary" onclick="document.querySelector(\'#task-detail-dialog\').close()">完成</button>';$("#task-detail").innerHTML=`<header><div><p class="eyebrow">REVIEW · ${escapeHtml(task.status||"UNKNOWN")}</p><h2>${escapeHtml(task.agent_id||"Agent 任务")}</h2></div><button class="icon-button" onclick="document.querySelector('#task-detail-dialog').close()">×</button></header><p class="form-note">指派原因：${escapeHtml(task.assignment?.reason||"未说明")}</p><div class="answer">${escapeHtml(task.conclusion?.answer||task.conclusion?.error_code||"任务尚未生成最终结果。")}</div><h3>证据标识</h3><ul class="citation-list">${evidence}</ul><h3>冻结计划摘要</h3><p class="plan-summary">${plan}</p><h3>协作备注</h3><div id="review-comments" class="form-note">正在读取协作备注…</div><h3>审批状态</h3><p>${task.approval?.required?`需要审批（${escapeHtml(task.approval.approval_id||"审批标识将在控制动作中校验")}）`:"当前不等待审批。"}</p><p class="form-note">审批决定会由 Runtime 校验指派关系、审批标识、状态与一次性消费规则，并写入治理审计。</p><div class="detail-actions">${approvalActions}</div>`;$("#task-detail-dialog").showModal();try{const comments=await api(`/api/review/runs/${encodeURIComponent(runId)}/comments`);$("#review-comments").innerHTML=(comments.items||[]).map(item=>`<p><strong>${escapeHtml(item.author_id||"审查人")}</strong> · ${escapeHtml(item.message||"")}</p>`).join("")||"暂无协作备注。"}catch(error){$("#review-comments").textContent="协作备注暂不可用。"}const decide=async approved=>{try{await api(`/api/review/runs/${encodeURIComponent(runId)}/approval`,{method:"POST",body:JSON.stringify({approved,approval_id:task.approval.approval_id,reason:approved?"review approved":"review rejected"})});$("#task-detail-dialog").close();toast(approved?"已提交批准决定":"已提交拒绝决定");loadReviewRuns()}catch(error){toast(error.message)}};$("#review-approve")?.addEventListener("click",()=>decide(true));$("#review-reject")?.addEventListener("click",()=>decide(false))}catch(error){toast(error.message)}}
function renderConsoleServices(items){const root=$("#console-list");if(!items.length){root.innerHTML='<div class="empty-state">没有可用的服务状态。</div>';return}root.innerHTML="";items.forEach(item=>{const card=document.createElement("article");card.className="service-card";card.innerHTML=`<div><h3>${escapeHtml(item.service)}</h3><p>就绪检查 HTTP ${escapeHtml(item.http_status||"不可达")}</p></div><span class="${statusClass(item.status)}">${escapeHtml(item.status)}</span>`;root.append(card)})}
