function renderReleaseCatalogPagination(result){const root=$("#release-catalog-pagination"),totalItems=Number(result.total_items||0),pageSize=Number(result.limit||8),totalPages=Math.max(1,Math.ceil(totalItems/pageSize));state.releaseCatalogPage=Math.min(state.releaseCatalogPage,totalPages);root.hidden=totalItems<=pageSize;root.replaceChildren();if(root.hidden)return;const status=document.createElement("span");status.className="pagination-summary";status.textContent=`第 ${state.releaseCatalogPage} / ${totalPages} 页，共 ${totalItems} 个 Agent`;root.append(status);const addButton=(label,page,disabled=false)=>{const button=document.createElement("button");button.className="ghost pagination-button";button.type="button";button.textContent=label;button.disabled=disabled;button.addEventListener("click",()=>loadReleaseCatalog(page));root.append(button)};addButton("上一页",state.releaseCatalogPage-1,state.releaseCatalogPage<=1);for(const item of paginationPages(state.releaseCatalogPage,totalPages)){if(item==="…"){const gap=document.createElement("span");gap.className="pagination-gap";gap.textContent=item;root.append(gap)}else{const button=document.createElement("button");button.className=`ghost pagination-button${item===state.releaseCatalogPage?" active":""}`;button.type="button";button.textContent=String(item);button.disabled=item===state.releaseCatalogPage;button.addEventListener("click",()=>loadReleaseCatalog(item));root.append(button)}}addButton("下一页",state.releaseCatalogPage+1,state.releaseCatalogPage>=totalPages)}
async function loadReleaseCatalog(page=state.releaseCatalogPage){
  state.releaseCatalogPage=Math.max(1,Number(page)||1);
  const root=$("#release-catalog-list");
  const pagination=$("#release-catalog-pagination");
  $("#release-catalog-section").hidden=false;
  pagination.hidden=true;
  root.innerHTML='<div class="empty-state">正在读取 Agent 发布目录…</div>';
  try{
    const result=await api(`/api/console/agents?limit=8&page=${state.releaseCatalogPage}`);
    const totalPages=Math.max(1,Math.ceil(Number(result.total_items||0)/Number(result.limit||8)));
    if(state.releaseCatalogPage>totalPages){state.releaseCatalogPage=totalPages;return loadReleaseCatalog(totalPages)}
    const agents=result.items||[];
    if(!agents.length){root.innerHTML='<div class="empty-state">当前租户没有可展示的 Agent Draft。</div>';renderReleaseCatalogPagination(result);return}
    root.innerHTML="";
    for(const agent of agents){
      const agentId=agent.agent_id||"";
      const card=document.createElement("article");
      card.className="task-card release-catalog-card";
      card.innerHTML=`<div><p class="eyebrow">DRAFT REVISION ${escapeHtml(agent.revision||0)}</p><h3>${escapeHtml(agentId||"Agent")}</h3><div class="release-catalog-content">正在读取冻结 Version 与 Release 摘要…</div></div>`;
      root.append(card);
      const [versionResult,releaseResult]=await Promise.allSettled([
        api(`/api/console/agents/${encodeURIComponent(agentId)}/versions`),
        api(`/api/console/agents/${encodeURIComponent(agentId)}/releases`),
      ]);
      const versions=versionResult.status==="fulfilled"?(versionResult.value.items||[]):[];
      const releases=releaseResult.status==="fulfilled"?(releaseResult.value.items||[]):[];
      const content=card.querySelector(".release-catalog-content");
      const versionRows=versions.length?versions.map(item=>{
        const semantic=escapeHtml(item.semantic_version||"未命名");
        const summary=escapeHtml(item.change_summary||"未填写变更摘要");
        return `<div class="catalog-row"><div><strong>v${semantic}</strong><span>Version ID: ${escapeHtml(item.version_id||"-")}</span><small>基于 Draft Revision ${escapeHtml(item.source_revision||0)} · ${summary}</small></div></div>`;
      }).join(""):'<p class="catalog-empty">尚未冻结 Version。请先使用“校验并冻结 Version”创建不可变版本。</p>';
      const releaseRows=releases.length?releases.map(item=>`<li>${escapeHtml(item.environment||"-")} · ${escapeHtml(item.status||"-")} · ${escapeHtml(item.release_id||"").slice(0,12)}</li>`).join(""):'<li>尚未创建 Release。</li>';
      content.innerHTML=`<section class="catalog-block"><h4>已冻结 Version</h4><div class="version-list">${versionRows}</div></section><section class="catalog-block"><h4>Release</h4><ul>${releaseRows}</ul></section>`;
      if(hasPermission("release:create")){
        versions.forEach((version,index)=>{
          const row=content.querySelectorAll(".catalog-row")[index];
          if(!row)return;
          const button=document.createElement("button");
          button.className="ghost catalog-action";
          button.type="button";
          button.textContent="用于创建 Release";
          button.addEventListener("click",()=>{
            $("#release-agent-id").value=agentId;
            $("#release-version-id").value=version.version_id||"";
            $("#release-create-form").scrollIntoView?.({behavior:"smooth",block:"center"});
            toast(`已带入 ${agentId} 的 v${version.semantic_version||"未命名"}`);
          });
          row.append(button);
        });
      }
      if(versionResult.status==="rejected"||releaseResult.status==="rejected"){
        const notice=document.createElement("p");
        notice.className="form-note";
        notice.textContent="部分发布目录暂不可用，请稍后刷新。";
        content.append(notice);
      }
    }
    renderReleaseCatalogPagination(result);
  }catch(error){root.innerHTML=`<div class="empty-state">${escapeHtml(error.message)}</div>`;pagination.hidden=true}
}
function renderGoldenCandidates(items){const root=$("#golden-candidate-list");$("#golden-candidate-section").hidden=false;if(!items.length){root.innerHTML='<div class="empty-state">目前没有待审核的 Golden Candidate。</div>';return}root.innerHTML="";items.forEach(item=>{const card=document.createElement("article");card.className="task-card review-card";card.innerHTML=`<div><p class="eyebrow">${escapeHtml(item.status||"PENDING")}</p><h3>${escapeHtml(item.question||"未提供问题")}</h3><p>建议基准：${escapeHtml(item.groundTruth||"未提供")}</p><small>${escapeHtml((item.tags||[]).join(" · "))}</small></div><div class="task-meta"><button class="ghost">审核</button></div>`;card.querySelector("button").addEventListener("click",()=>{state.activeGoldenCandidate=item;$("#golden-candidate-summary").textContent=`候选 ${item.id}：${item.question||""}`;$("#golden-review-dialog").showModal()});root.append(card)})}
async function loadGoldenCandidates(){const root=$("#golden-candidate-list");if(!hasPermission("eval:golden:review"))return;root.innerHTML='<div class="empty-state">正在读取候选样本…</div>';try{const result=await api("/api/console/golden-candidates");renderGoldenCandidates(result.items||[])}catch(error){root.innerHTML=`<div class="empty-state">${escapeHtml(error.message)}</div>`}}
function escapeHtml(value){return String(value??"").replace(/[&<>'"]/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[char]))}
async function loadConnectorDlq(){const section=$("#connector-dlq-section"),root=$("#connector-dlq-list");section.hidden=false;root.innerHTML='<div class="empty-state">正在读取 Connector 工件死信…</div>';try{const result=await api("/api/console/connector-artifact-dlq");const items=result.items||[];root.innerHTML=items.length?"":'<div class="empty-state">当前没有 Connector 工件死信。</div>';items.forEach(item=>{const card=document.createElement("article");card.className="task-card";card.innerHTML=`<div><p class="eyebrow">${escapeHtml(item.dead_lettered_at||"")}</p><h3>${escapeHtml(item.outbox_id||"")}</h3><p>任务 ${escapeHtml(item.task_id||"")} · 尝试 ${escapeHtml(item.attempts||0)} 次 · ${escapeHtml(item.last_error||"未知错误")}</p></div><div class="task-meta">${hasPermission("connector:artifact:dlq:requeue")?'<button class="ghost">重排</button>':""}</div>`;card.querySelector("button")?.addEventListener("click",async()=>{if(!confirm(`确认重排 ${item.outbox_id}？该操作不会再次执行本机工具。`))return;await api(`/api/console/connector-artifact-dlq/${encodeURIComponent(item.outbox_id)}/requeue`,{method:"POST",body:JSON.stringify({confirm_outbox_id:item.outbox_id})});toast("死信已进入重试队列");loadConnectorDlq()});root.append(card)})}catch(error){root.innerHTML=`<div class="empty-state">${escapeHtml(error.message)}</div>`}}
async function loadModelRouteReleases(){const section=$("#model-route-section"),root=$("#model-route-list");section.hidden=false;root.innerHTML='<div class="empty-state">正在读取模型路由发布…</div>';try{const result=await api("/api/console/model-route-releases"),items=result.items||[];root.innerHTML=items.length?"":'<div class="empty-state">尚无模型路由发布。</div>';items.forEach(item=>{const card=document.createElement("article");card.className="task-card";card.innerHTML=`<div><p class="eyebrow">${escapeHtml(item.status||"UNKNOWN")}</p><h3>${escapeHtml(item.routeName||"-")} → ${escapeHtml(item.canaryTarget||"-")}</h3><p>${escapeHtml(item.id||"")} · Canary ${escapeHtml(item.canaryPercent||0)}%</p></div><div class="task-meta"><button class="ghost monitor-route">观测</button>${hasPermission("model:route:rollback")&&!["PROMOTED","ROLLED_BACK"].includes(item.status)?'<button class="ghost rollback-route">回滚</button>':""}</div>`;card.querySelector(".monitor-route")?.addEventListener("click",async()=>{try{await api(`/api/console/model-route-releases/${encodeURIComponent(item.id)}/monitor`,{method:"POST",body:"{}"});toast("已执行一次路由观测");loadModelRouteReleases()}catch(error){toast(error.message)}});card.querySelector(".rollback-route")?.addEventListener("click",async()=>{if(!confirm(`确认回滚模型路由发布 ${item.id}？`))return;try{await api(`/api/console/model-route-releases/${encodeURIComponent(item.id)}/rollback`,{method:"POST",body:JSON.stringify({confirmReleaseId:item.id,reason:"console manual rollback"})});toast("模型路由已回滚");loadModelRouteReleases()}catch(error){toast(error.message)}});root.append(card)})}catch(error){root.innerHTML=`<div class="empty-state">${escapeHtml(error.message)}</div>`}}
async function loadLlmQuotas(){const section=$("#llm-quota-section"),root=$("#llm-quota-list");section.hidden=false;root.innerHTML='<div class="empty-state">正在读取 LLM 配额…</div>';try{const result=await api("/api/console/llm-quotas"),items=result.items||[];root.innerHTML=items.length?items.map(item=>`<article class="task-card"><div><h3>${escapeHtml(item.subject)}</h3><p>${escapeHtml(item.daily_token_limit)} Token/日 · $${escapeHtml(item.daily_cost_limit_usd)} ${escapeHtml(item.currency||"USD")}/日</p></div></article>`).join(""):'<div class="empty-state">尚未设置租户专属配额，将使用 Gateway 安全默认值。</div>'}catch(error){root.innerHTML=`<div class="empty-state">${escapeHtml(error.message)}</div>`}}
async function loadAuditExports(){const section=$("#audit-export-section"),root=$("#audit-export-list");section.hidden=false;root.innerHTML='<div class="empty-state">正在读取 WORM 导出作业…</div>';try{const result=await api("/api/console/audit-exports"),items=result.items||[];root.innerHTML=items.length?"":'<div class="empty-state">尚未发起审计导出。</div>';items.forEach(item=>{const card=document.createElement("article");card.className="task-card";const proof=item.result||{};card.innerHTML=`<div><p class="eyebrow">${escapeHtml(item.status||"UNKNOWN")} · 尝试 ${escapeHtml(item.attempts||0)}/${escapeHtml(item.max_attempts||0)}</p><h3>${escapeHtml(item.job_id||"")}</h3><p>${proof.object_key?`对象：${escapeHtml(proof.object_key)}<br>Merkle：${escapeHtml(String(proof.merkle_root||"").slice(0,24))}…<br>保留至：${escapeHtml(proof.retention_until||"")}`:escapeHtml(item.last_error||item.requested_at||"等待 Worker 处理")}</p></div><div class="task-meta">${["FAILED","DLQ"].includes(item.status)&&hasPermission("audit:export:requeue")?'<button class="ghost requeue-export">重排</button>':""}</div>`;card.querySelector(".requeue-export")?.addEventListener("click",async()=>{if(!confirm(`确认重排导出 ${item.job_id}？`))return;try{await api(`/api/console/audit-exports/${encodeURIComponent(item.job_id)}/requeue`,{method:"POST",body:JSON.stringify({confirmJobId:item.job_id})});toast("导出已重新入队");loadAuditExports()}catch(error){toast(error.message)}});root.append(card)})}catch(error){root.innerHTML=`<div class="empty-state">${escapeHtml(error.message)}</div>`}}
async function showArtifactContent(runId,artifactId,baseArtifactId=""){try{const comparison=Boolean(baseArtifactId);const path=comparison?`/api/workspace/runs/${encodeURIComponent(runId)}/artifacts/${encodeURIComponent(artifactId)}/compare/${encodeURIComponent(baseArtifactId)}`:`/api/workspace/runs/${encodeURIComponent(runId)}/artifacts/${encodeURIComponent(artifactId)}/preview`;const result=await api(path);$("#artifact-preview-title").textContent=comparison?`${result.logical_name} 版本差异`:`${result.logical_name} · v${result.version}`;$("#artifact-preview-meta").textContent=comparison?`v${result.base_version} → v${result.target_version}${result.truncated?" · 差异已截断":""}`:`${result.media_type} · SHA-256 ${String(result.content_sha256||"").slice(0,16)}…${result.sha256_verified===true?" · 完整性已验证":""}${result.truncated?" · 预览已截断":""}`;$("#artifact-preview-content").textContent=comparison?result.diff||"两个版本没有文本差异。":result.content;$("#artifact-preview-dialog").showModal()}catch(error){toast(error.message)}}
async function decideArtifactIngestion(runId,artifactId,approved){const reason=prompt(approved?"请输入批准进入 RAG 的理由：":"请输入拒绝理由：",approved?"已确认扫描范围与数据级别":"");if(!reason)return;try{await api(`/api/workspace/runs/${encodeURIComponent(runId)}/artifacts/${encodeURIComponent(artifactId)}/ingestion-decision`,{method:"POST",body:JSON.stringify({approved,reason,confirm_artifact_id:artifactId})});toast(approved?"已批准，摄取 Relay 将自动提交 RAG":"已拒绝，产物不会进入 RAG");openTask(runId)}catch(error){toast(error.message)}}
function visibleValue(value,fallback="-"){if(value===null||value===undefined||value==="")return fallback;if(typeof value==="boolean")return value?"是":"否";return String(value)}
function metadataSummary(metadata={}){return Object.entries(metadata).filter(([,value])=>value!==null&&value!==undefined&&value!=="").map(([key,value])=>{if(key==="checks"&&Array.isArray(value))return `门禁 ${value.filter(item=>item.passed).length}/${value.length} 通过`;if(key==="budget_report"&&typeof value==="object")return `上下文 Token ${value.used_message_tokens||0} / 证据 Token ${value.used_evidence_tokens||0}`;const rendered=Array.isArray(value)?value.join("、"):typeof value==="object"?JSON.stringify(value):visibleValue(value);return `${key}=${rendered}`}).join(" · ")}
function renderWorkspaceExecution(task){const execution=task.execution||{},release=execution.release||{},snapshot=execution.snapshot||{},plan=execution.plan||{},intent=plan.intent||{},complexity=plan.complexity||{},route=plan.route||{},model=execution.model||{},budget=execution.budget||{},context=execution.context||{},token=context.token_budget||{};const checks=(plan.admission_checks||[]).map(item=>`<li class="${item.passed?"check-pass":"check-fail"}"><strong>${escapeHtml(item.check||"检查")}</strong><span>${item.passed?"通过":"未通过"} · ${escapeHtml(item.reason||"")}</span></li>`).join("")||"<li>没有计划准入记录。</li>";const retrieval=(execution.retrieval||[]).map(item=>`<li><strong>${escapeHtml(item.retrieval_profile||"DEFAULT")}</strong><span>${escapeHtml(item.rag_status||"unknown")} · ${visibleValue(item.result_count,0)} 条结果${item.context_degraded?" · 已降级":""}</span><small>${escapeHtml(item.query||"")}</small></li>`).join("")||"<li>本次没有执行知识检索。</li>";const tools=(execution.tools||[]).map(item=>`<li><strong>${escapeHtml(item.tool||"工具")}</strong><span>${item.success?"执行成功":"执行失败"} · scope=${escapeHtml(item.scope||"-")}${item.match_count!==null&&item.match_count!==undefined?` · ${item.match_count} 条命中`:""}</span></li>`).join("")||"<li>本次没有调用工具。</li>";const timeline=(execution.timeline||[]).map(item=>`<li><span class="timeline-sequence">#${escapeHtml(item.sequence)}</span><div><strong>${escapeHtml(item.event_type||"event")}</strong><time>${item.occurred_at?new Date(item.occurred_at).toLocaleString():""}</time><p>${escapeHtml(metadataSummary(item.metadata||{})||item.status||"")}</p></div></li>`).join("")||"<li class=\"timeline-empty\">事件历史暂不可用。</li>";return `<section class="execution-observability"><div class="execution-heading"><div><p class="eyebrow">CONTROLLED EXECUTION</p><h3>受控执行详情</h3></div><span>${(execution.timeline||[]).length} 条事件</span></div><div class="observability-grid"><article><h4>Release / Snapshot</h4><dl><dt>Release</dt><dd>${escapeHtml(release.release_id||release.status||"未解析")}</dd><dt>环境 / 状态</dt><dd>${escapeHtml([release.environment,release.status].filter(Boolean).join(" · ")||"-")}</dd><dt>Snapshot</dt><dd class="mono">${escapeHtml(snapshot.snapshot_id||"-")}</dd><dt>Agent / Graph</dt><dd>${escapeHtml(snapshot.agent_version||"-")}<br>${escapeHtml(snapshot.graph_version||"-")}</dd></dl></article><article><h4>Planner / Executor</h4><dl><dt>Plan</dt><dd class="mono">${escapeHtml(plan.plan_id||"-")}</dd><dt>阶段 / 执行器</dt><dd>${escapeHtml(plan.plan_stage||"-")} · ${escapeHtml(plan.executor_profile||"-")}</dd><dt>意图 / 复杂度</dt><dd>${escapeHtml(intent.name||"-")} (${visibleValue(intent.confidence)}) · ${escapeHtml(complexity.level||"-")} ${visibleValue(complexity.score,"")}</dd><dt>路由</dt><dd>${escapeHtml(route.route||"-")} · ${escapeHtml(route.quality_tier||"-")}</dd></dl></article><article><h4>模型</h4><dl><dt>路由 / Revision</dt><dd>${escapeHtml((model.routes||[]).join("、")||"本次未固定模型事件")}</dd><dt>策略版本</dt><dd class="mono">${escapeHtml(model.model_policy_version||"-")}</dd><dt>决策事件 / 计费调用</dt><dd>${visibleValue(model.decision_request_events,0)} / ${visibleValue(model.billed_llm_calls,0)}</dd><dt>降级链</dt><dd>${escapeHtml((model.fallback_chain||[]).join(" → ")||"无")}</dd></dl></article><article><h4>成本与额度</h4><dl><dt>成本</dt><dd>$${visibleValue(budget.spent_cost_usd,0)} / $${visibleValue(budget.max_cost_usd,0)}</dd><dt>步骤</dt><dd>${visibleValue(budget.step_count,0)} / ${visibleValue(budget.max_steps,0)}</dd><dt>LLM / 工具 / 检索</dt><dd>${visibleValue(budget.llm_calls,0)} / ${visibleValue(budget.tool_calls,0)} / ${visibleValue(budget.retrieval_rounds,0)}</dd><dt>延迟</dt><dd>${visibleValue(execution.latency_ms,0)} ms</dd></dl></article><article><h4>Context</h4><dl><dt>历史消息</dt><dd>${visibleValue(context.selected_history_count,0)} 条</dd><dt>RAG 状态</dt><dd>${escapeHtml(context.rag_status||"-")}${context.degraded?" · 已降级":""}</dd><dt>消息 / 证据 Token</dt><dd>${visibleValue(token.used_message_tokens,0)} / ${visibleValue(token.used_evidence_tokens,0)}</dd><dt>分配策略</dt><dd>${escapeHtml(token.strategy||"-")}</dd></dl></article><article><h4>允许工具与准入</h4><p class="tool-scope">${escapeHtml((plan.allowed_tool_scope||[]).join("、")||"未发布工具")}</p><ul class="check-list">${checks}</ul></article></div><div class="execution-columns"><section><h4>检索记录</h4><ul class="execution-list">${retrieval}</ul></section><section><h4>工具调用</h4><ul class="execution-list">${tools}</ul></section></div><section class="timeline-panel"><div class="timeline-title"><h4>事件时间线</h4><span>不展示原始 Prompt、模型响应正文和敏感工具输出</span></div><ol class="event-timeline">${timeline}</ol></section></section>`}
async function openTask(runId){try{const task=await api(`/api/workspace/runs/${encodeURIComponent(runId)}`);const citations=(task.citations||[]).map(item=>`<li><strong>${escapeHtml(item.evidence_id||"证据")}</strong> ${escapeHtml(item.source||"")}</li>`).join("")||"<li>本次没有可展示的引用。</li>";const artifacts=(task.artifacts||[]).map(item=>{if(item.status==="unavailable")return"<li>产物索引暂不可用；任务结果不受影响。</li>";const artifactId=escapeHtml(item.artifact_id||""),previousId=escapeHtml(item.previous_artifact_id||""),ingestion=item.rag_ingestion||null;const ingestionActions=ingestion?.status==="AWAITING_APPROVAL"&&hasPermission("rag:ingest:approve")?`<button class="primary artifact-ingest-approve" data-artifact-id="${artifactId}">批准进入 RAG</button><button class="ghost artifact-ingest-reject" data-artifact-id="${artifactId}">拒绝</button>`:"";const ingestionState=ingestion?`<br><small>RAG 摄取：${escapeHtml(ingestion.status)}${ingestion.ingestion_job_id?` · ${escapeHtml(ingestion.ingestion_job_id)}`:""}</small>`:"";return `<li><strong>${escapeHtml(item.logical_name||item.artifact_type||"产物")} · v${escapeHtml(item.version||1)}</strong> · ${escapeHtml(item.media_type||"-")}<br><small>${artifactId} · SHA-256 ${escapeHtml(String(item.content_sha256||"").slice(0,12))}…</small>${ingestionState}<div class="artifact-actions"><button class="ghost artifact-preview" data-artifact-id="${artifactId}">在线预览</button>${previousId?`<button class="ghost artifact-compare" data-artifact-id="${artifactId}" data-base-artifact-id="${previousId}">对比上一版</button>`:""}${ingestionActions}<a class="text-link" href="/api/workspace/runs/${encodeURIComponent(runId)}/artifacts/${encodeURIComponent(item.artifact_id||"")}/download">下载</a></div></li>`}).join("")||"<li>本次尚未登记不可变产物。</li>";const active=!terminal.has(task.status),canControl=task.can_control===true;const detail=$("#task-detail");const expanded=detail.dataset.runId===runId?[...detail.querySelectorAll("details[open][data-detail-key]")].map(node=>node.dataset.detailKey):[];detail.dataset.runId=runId;detail.dataset.runStatus=task.status||"";detail.innerHTML=`<header><div><p class="eyebrow">${escapeHtml(task.status||"UNKNOWN")}</p><h2>${escapeHtml(task.agent_id||"Agent 任务")}</h2><p class="run-identity mono">${escapeHtml(task.run_id||runId)}</p></div><button class="icon-button" onclick="document.querySelector('#task-detail-dialog').close()">×</button></header><div class="answer">${escapeHtml(task.answer||task.error_code||"任务尚未生成最终结果。")}</div><div class="result-columns"><section><h3>引用与依据</h3><ul class="citation-list">${citations}</ul></section><section><h3>任务产物</h3><ul class="citation-list">${artifacts}</ul></section></div>${renderWorkspaceExecution(task)}${canControl?"":'<p class="form-note">你拥有该任务的只读共享权限；取消、补充指令和审批仍仅属于任务创建者。</p>'}<div class="detail-actions">${active&&canControl?'<button id="cancel-run" class="ghost">取消任务</button>':""}<button class="primary" onclick="document.querySelector('#task-detail-dialog').close()">完成</button></div>`;compactExecutionDetails();detail.querySelectorAll("details[data-detail-key]").forEach(node=>node.open=expanded.includes(node.dataset.detailKey));$("#task-detail-dialog").showModal();document.querySelectorAll("#task-detail .artifact-preview").forEach(button=>button.addEventListener("click",()=>showArtifactContent(runId,button.dataset.artifactId)));document.querySelectorAll("#task-detail .artifact-compare").forEach(button=>button.addEventListener("click",()=>showArtifactContent(runId,button.dataset.artifactId,button.dataset.baseArtifactId)));document.querySelectorAll("#task-detail .artifact-ingest-approve").forEach(button=>button.addEventListener("click",()=>decideArtifactIngestion(runId,button.dataset.artifactId,true)));document.querySelectorAll("#task-detail .artifact-ingest-reject").forEach(button=>button.addEventListener("click",()=>decideArtifactIngestion(runId,button.dataset.artifactId,false)));if(active&&canControl&&workspaceEventAbort===null){workspaceEventCursor=0;startWorkspaceEvents(runId)}else if(!active&&workspaceEventAbort){workspaceEventAbort.abort();workspaceEventAbort=null;workspaceEventCursor=0}$("#cancel-run")?.addEventListener("click",async()=>{try{await api(`/api/workspace/runs/${encodeURIComponent(runId)}/cancel`,{method:"POST",body:"{}"});$("#task-detail-dialog").close();toast("已提交取消请求");loadTasks()}catch(error){toast(error.message)}})}catch(error){toast(error.message)}}
function newTaskSessionId(){return `web_${crypto.randomUUID().replaceAll("-","")}`}
async function loadTaskModelRoutes(){const select=$("#model-route-input"),hint=$("#model-route-hint"),agentId=$("#agent-input").value,environment=$("#environment-input").value;let sessionId=$("#task-session-id").value;if(!sessionId){sessionId=newTaskSessionId();$("#task-session-id").value=sessionId}select.disabled=true;select.innerHTML='<option value="">正在读取已发布模型…</option>';hint.textContent="正在解析本任务会话的 Release Snapshot…";try{const catalog=await api(`/api/workspace/model-routes?agent_id=${encodeURIComponent(agentId)}&environment=${encodeURIComponent(environment)}&session_id=${encodeURIComponent(sessionId)}`),items=catalog.items||[];select.replaceChildren();for(const item of items){const option=document.createElement("option");option.value=item.route_name;option.textContent=`${item.route_name} · ${(item.models||[]).join(" → ")}`;select.append(option)}if(!items.length)throw new Error("当前发布快照没有可执行模型路由");select.value=catalog.default_route||items[0].route_name;select.disabled=false;hint.textContent=`已固定 Release ${catalog.release_id||"-"} / Snapshot ${catalog.snapshot_id||"-"}；Gateway 仍按该路由的版本、配额和降级链执行。`}catch(error){select.innerHTML='<option value="">没有可用的已发布模型</option>';hint.textContent=`无法读取模型选项：${error.message}`;toast(error.message)}}
async function openTaskDialog(){$("#task-session-id").value=newTaskSessionId();$("#task-dialog").showModal();$("#task-input").focus();await loadTaskModelRoutes()}
function hasPermission(permission){return state.session?.permissions.includes(permission)||state.session?.roles.includes(permission)}
function addReviewControls(){const actions=$("#task-detail .detail-actions");if(!actions||actions.dataset.reviewControls||!state.activeReviewRun||!$("#task-detail").textContent.includes("REVIEW"))return;actions.dataset.reviewControls="true";if(hasPermission("run:review:comment")){const button=document.createElement("button");button.className="ghost";button.textContent="添加备注";button.addEventListener("click",()=>$("#review-comment-dialog").showModal());actions.prepend(button)}if(hasPermission("run:review:transfer")){const button=document.createElement("button");button.className="ghost";button.textContent="转交";button.addEventListener("click",()=>$("#review-transfer-dialog").showModal());actions.prepend(button)}if(hasPermission("run:review:assign")){const button=document.createElement("button");button.className="ghost";button.textContent="添加共同审查人";button.addEventListener("click",()=>$("#review-collaborator-dialog").showModal());actions.prepend(button)}if(hasPermission("run:review:label")){const button=document.createElement("button");button.className="ghost";button.textContent="专家标注";button.addEventListener("click",()=>$("#review-feedback-dialog").showModal());actions.prepend(button)}if(hasPermission("evidence:content:read")){document.querySelectorAll("#task-detail .citation-list li").forEach(item=>{const evidenceId=item.querySelector("strong")?.textContent?.trim();if(!evidenceId||item.querySelector(".evidence-read"))return;const button=document.createElement("button");button.className="ghost evidence-read";button.textContent="查看授权正文";button.addEventListener("click",async()=>{try{const evidence=await api(`/api/review/runs/${encodeURIComponent(state.activeReviewRun)}/evidence/${encodeURIComponent(evidenceId)}`);let body=item.querySelector(".evidence-body");if(!body){body=document.createElement("div");body.className="evidence-body";item.append(body)}body.textContent=`数据域：${evidence.data_domain||"未声明"}\nSHA-256：${evidence.content_sha256}\n\n${evidence.content}` }catch(error){toast(error.message)}});item.append(button)})}}
// 任务详情通过 innerHTML 原子替换；统一在 DOM 变更后补齐审查控件和渐进披露布局。
new MutationObserver(addReviewControls).observe($("#task-detail"),{childList:true});
function addWikiCompileControl(){const actions=$("#task-detail .detail-actions");if(!actions||actions.dataset.wikiControl||!state.activeReviewRun||!$("#task-detail").textContent.includes("REVIEW")||!hasPermission("knowledge:compile"))return;actions.dataset.wikiControl="true";const button=document.createElement("button");button.type="button";button.className="ghost";button.textContent="编译为 Wiki 候选";button.addEventListener("click",openWikiCompiler);actions.prepend(button)}
new MutationObserver(addWikiCompileControl).observe($("#task-detail"),{childList:true});
async function openReviewAssignmentDialog(){
  const select=$("#workspace-reviewer-select"),submit=$("#workspace-review-assignment-submit");
  select.innerHTML='<option value="">正在加载当前租户的可用审查专家…</option>';
  submit.disabled=true;
  $("#workspace-review-assignment-dialog").showModal();
  try{
    const result=await api("/api/workspace/reviewers"),reviewers=result.items||[];
    select.innerHTML='<option value="">请选择审查专家</option>';
    reviewers.forEach(reviewer=>{
      const option=document.createElement("option");
      option.value=reviewer.user_id||"";
      option.textContent=`${reviewer.username||"未命名用户"} · ${reviewer.user_id||""}`;
      select.append(option);
    });
    submit.disabled=!reviewers.length;
    if(!reviewers.length)toast("当前租户没有已启用的审查专家，请先在租户与用户中完成授权");
  }catch(error){
    select.innerHTML='<option value="">审查专家目录暂不可用</option>';
    toast(error.message);
  }
}
