async function loadSession(){state.session=await api("/api/session");const development=state.session.authentication==="local-development",roles=state.session.roles||[],permissions=state.session.permissions||[],roleLabels={"platform-super-admin":"最高管理员","platform-operator":"平台操作员","agent-reviewer":"审查专家","governance-auditor":"治理审计员","agent-user":"业务用户"},primaryRole=roles.map(role=>roleLabels[role]).find(Boolean)||"未分配角色",user=state.session.username||state.session.user_id||state.headers["X-User-Id"],tenant=state.session.tenant_id||state.headers["X-Tenant-Id"];$("#development-identity").hidden=!development;$("#identity-summary").innerHTML=`<strong>${escapeHtml(user||"未选择本地身份")}</strong><small>租户：${escapeHtml(tenant||"-")}</small><br><span class="identity-badge">${escapeHtml(development?`本地模拟 · ${primaryRole}`:primaryRole)}</span>`;const granted=[];document.querySelectorAll("[data-requires]").forEach(control=>{const allowed=hasPermission(control.dataset.requires);/* 前端隐藏只改善信息架构；后端仍对每个接口执行同一权限校验。 */control.hidden=!allowed;control.disabled=false;if(allowed)granted.push(control.textContent.trim())});$("#access-summary").textContent=granted.length?`可用工作区：我的任务、${granted.join("、")}`:"可用工作区：我的任务";$("#account-display").textContent=user||"未选择本地身份";$("#account-context").textContent=`${tenant||"无租户"} · ${primaryRole}`;$("#account-authentication-note").textContent=development?"本地模拟身份仅用于 Compose 联调；切换模板会改变浏览器请求头，不会写入真实用户目录。":"当前角色与权限来自经验证的 OIDC 登录声明。";const details=$("#account-details");details.replaceChildren();[["登录名 / User ID",user||"-"],["租户",tenant||"-"],["角色",roles.map(role=>roleLabels[role]||role).join("、")||"未分配"]].forEach(([label,value])=>{const dt=document.createElement("dt"),dd=document.createElement("dd");dt.textContent=label;dd.textContent=value;details.append(dt,dd)});renderAccessChips($("#account-workspaces"),["我的任务",...granted],"没有额外工作区权限");renderAccessChips($("#account-permission-list"),permissions,"没有授予业务权限");const manage=$("#account-open-identity");manage.hidden=!hasPermission("identity:users:read");$("#logout-button").hidden=false;$("#logout-button").textContent=development?"结束本地演示":"退出登录";$("#switch-account-button").textContent=development?"切换本地身份":"切换账号"}
