// 运行详情承载审计信息而非聊天记录。首次打开只保留结论、版本、成本等决策所需摘要；
// 计划、检索、工具和完整事件链放入原生 details，避免长任务把工作区页面撑成日志墙。
// 折叠标记属于本次渲染的网格，不能留在复用的弹窗上，否则第二个任务不再折叠。
function compactExecutionDetails(){
  const host=$("#task-detail"),grid=host.querySelector(".observability-grid");
  if(!grid||grid.dataset.compacted==="true")return;
  grid.dataset.compacted="true";
  const fold=(parent,nodes,label,key,className="inline-detail")=>{
    const disclosure=document.createElement("details");
    disclosure.className=className;disclosure.dataset.detailKey=key;
    const summary=document.createElement("summary");summary.textContent=label;
    disclosure.append(summary);parent.append(disclosure);
    nodes.forEach(node=>disclosure.append(node));return disclosure;
  };
  const planner=grid.children[1],plan=planner?.querySelector("dl");
  if(plan){
    const summary=document.createElement("p");summary.className="card-summary";
    summary.textContent=plan.querySelectorAll("dd")[2]?.textContent||"计划摘要暂不可用";
    planner.insertBefore(summary,plan);
    fold(planner,[plan],"查看计划、执行器和路由","planner");
  }
  const context=grid.children[4],contextData=context?.querySelector("dl");
  if(contextData)fold(context,[contextData],"查看 Context 分配","context");
  const admission=grid.children[5];
  if(admission)fold(admission,[...admission.children].filter(node=>node.tagName!=="H4"),"查看工具范围与准入检查","admission");
  const columns=host.querySelector(".execution-columns"),timeline=host.querySelector(".timeline-panel");
  if(columns&&timeline){
    const parent=columns.parentElement;
    fold(parent,[columns,timeline],"检索、工具与事件详情","events","execution-deep-dive");
  }
  const evidence=host.querySelector(".result-columns section:first-child");
  const heading=evidence?.querySelector("h3"),list=evidence?.querySelector(".citation-list");
  if(heading&&list){
    // 空状态也是一个 li，但不是证据；只统计真正含 Evidence 标识的条目。
    const count=list.querySelectorAll("li strong").length;
    heading.remove();fold(evidence,[list],`RAG 与 Evidence · ${count} 条引用`,"evidence","evidence-detail");
  }
}
async function loadTenantCatalog(){
  const section=$("#tenant-catalog-section"),root=$("#tenant-catalog-list");
  if(!hasPermission("tenant:read"))return;
  section.hidden=false;root.innerHTML='<div class="empty-state">正在读取租户目录…</div>';
  try{
    const result=await api("/api/console/tenants"),items=result.items||[];
    state.tenants=items;
    const active=items.filter(item=>item.status==="active");
    setSelectOptions($("#identity-user-tenant"),active.map(item=>item.tenant_id));
    root.innerHTML=items.length?"":'<div class="empty-state">尚未创建租户。</div>';
    items.forEach(item=>{
      const card=document.createElement("article");card.className="task-card";
      card.innerHTML=`<div><h3>${escapeHtml(item.display_name)}</h3><p>ID：${escapeHtml(item.tenant_id)} · 区域：${escapeHtml(item.data_region)}<br>创建者：${escapeHtml(item.created_by)}</p></div><div class="task-meta"><span class="${statusClass(item.status)}">${escapeHtml(item.status)}</span>${hasPermission("tenant:write")?'<button class="ghost">管理</button>':""}</div>`;
      card.querySelector("button")?.addEventListener("click",()=>openTenantForm(item));
      root.append(card);
    });
  }catch(error){root.innerHTML=`<div class="empty-state">${escapeHtml(error.message)}</div>`}
}
$("#refresh-tenants").addEventListener("click",loadTenantCatalog);
function openTenantForm(tenant=null){const editing=Boolean(tenant);$("#tenant-form-mode").value=editing?"edit":"create";$("#tenant-form-title").textContent=editing?`管理租户：${tenant.tenant_id}`:"新建租户";$("#tenant-form-help").textContent=editing?"修改生命周期状态时必须填写变更原因；租户 ID 创建后不可修改。":"填写租户基础信息后创建；新建默认启用，无需填写变更原因。";$("#tenant-form-id").value=tenant?.tenant_id||"";$("#tenant-form-id").disabled=editing;$("#tenant-form-name").value=tenant?.display_name||"";$("#tenant-form-region").value=tenant?.data_region||"local";$("#tenant-form-status").value=tenant?.status||"active";$("#tenant-form-reason").value="";$("#tenant-form-status-field").hidden=!editing;$("#tenant-form-reason-field").hidden=!editing;$("#tenant-form-reason").required=editing;$("#tenant-form-reset").hidden=!editing;$("#tenant-form-submit").textContent=editing?"保存租户变更":"创建租户";if(editing)$("#tenant-form").scrollIntoView?.({behavior:"smooth",block:"center"})}
$("#tenant-form-reset").addEventListener("click",()=>openTenantForm());
$("#tenant-form").addEventListener("submit",async event=>{event.preventDefault();const editing=$("#tenant-form-mode").value==="edit",tenantId=$("#tenant-form-id").value.trim();try{const tenant=editing?await api(`/api/console/tenants/${encodeURIComponent(tenantId)}`,{method:"PUT",body:JSON.stringify({display_name:$("#tenant-form-name").value.trim(),data_region:$("#tenant-form-region").value.trim(),status:$("#tenant-form-status").value,reason:$("#tenant-form-reason").value.trim()})}):await api("/api/console/tenants",{method:"POST",body:JSON.stringify({tenant_id:tenantId,display_name:$("#tenant-form-name").value.trim(),data_region:$("#tenant-form-region").value.trim()})});toast(editing?`租户 ${tenant.tenant_id} 已更新`:`已创建租户 ${tenant.tenant_id}`);openTenantForm();await loadTenantCatalog()}catch(error){toast(error.message)}});
async function loadIdentityUsers(){const section=$("#identity-users-section"),root=$("#identity-user-list"),form=$("#identity-user-form"),canWrite=hasPermission("identity:users:write");if(!hasPermission("identity:users:read"))return;section.hidden=false;form.hidden=true;if(!state.session?.identity_management_available){root.innerHTML='<div class="empty-state"><strong>用户目录尚未启用</strong><p>当前是本地模拟身份模式：可验证界面权限，但不会创建、修改或保存真实账号。请用默认启动方式重启平台以启用 Keycloak/OIDC，然后以最高管理员登录。</p></div>';return}root.innerHTML='<div class="empty-state">正在读取用户与授权…</div>';try{const result=await api("/api/console/identity/users"),items=result.items||[];setSelectOptions($("#identity-user-roles"),result.roles||[]);setSelectOptions($("#identity-user-permissions"),result.permissions||[]);root.innerHTML=items.length?"":'<div class="empty-state">当前范围内没有可管理用户。</div>';items.forEach(item=>{const card=document.createElement("article");card.className=`task-card identity-user-card${item.protected?" protected":""}`;const tags=[...(item.roles||[]),...(item.current?["当前账号"]:[]),...(item.protected?["受保护的最高管理员"]:[])].map(value=>`<span>${escapeHtml(value)}</span>`).join("");card.innerHTML=`<div><h3>${escapeHtml(item.username)}</h3><p>租户：${escapeHtml(item.tenant_id||"-")} · ${item.enabled?"已启用":"已停用"}<br>平台 User ID：${escapeHtml(item.user_id)}<br>已分配 ${escapeHtml((item.permissions||[]).length)} 项权限</p><div class="identity-card-tags">${tags}</div></div><div class="task-meta">${canWrite&&!item.protected?'<button class="ghost">编辑授权</button>':item.protected?'<span>系统保护</span>':""}</div>`;card.querySelector("button")?.addEventListener("click",()=>{$("#identity-user-id").value=item.identity_id;$("#identity-user-name").value=item.username;$("#identity-user-subject").value=item.user_id;$("#identity-user-tenant").value=item.tenant_id;$("#identity-user-enabled").value=String(item.enabled);$("#identity-user-template").value="custom";selectValues($("#identity-user-roles"),item.roles);selectValues($("#identity-user-permissions"),item.permissions);$("#identity-user-reason").value="";form.hidden=false;form.scrollIntoView({behavior:"smooth",block:"center"})});root.append(card)})}catch(error){root.innerHTML=`<div class="empty-state">${escapeHtml(error.message)}</div>`}}
$("#refresh-identity-users").addEventListener("click",loadIdentityUsers);$("#identity-user-form").addEventListener("submit",async event=>{event.preventDefault();const id=$("#identity-user-id").value;if(!id)return toast("请先选择要编辑的用户");try{await api(`/api/console/identity/users/${encodeURIComponent(id)}`,{method:"PUT",body:JSON.stringify({tenant_id:$("#identity-user-tenant").value.trim(),enabled:$("#identity-user-enabled").value==="true",roles:selectedValues($("#identity-user-roles")),permissions:selectedValues($("#identity-user-permissions")),reason:$("#identity-user-reason").value.trim()})});toast("用户授权已更新，旧登录会话已撤销");await loadIdentityUsers()}catch(error){toast(error.message)}});
// Keep tenant/user administration out of the operations view. Moving existing nodes preserves
// their listeners and prevents duplicate forms or divergent authorization code paths.
function mountIdentityAdministration(){const view=$("#identity-view");["#tenant-catalog-section","#identity-users-section"].forEach(selector=>{const section=$(selector);if(section&&section.parentElement!==view)view.append(section)})}
mountIdentityAdministration();
(async()=>{try{await loadSession();await loadTasks()}catch(error){if(error.name==="SessionRedirectError")return;toast(error.message);$("#task-list").innerHTML=`<div class="empty-state">无法初始化工作区：${escapeHtml(error.message)}</div>`}})();
